// Client-side operational simulation engine for Argus.
//
// There is no backend, no database, and no real WebSocket server behind
// this dashboard. Every asset, position, telemetry reading, and event
// below is generated by deterministic math plus a seeded pseudo-random
// stream, advanced on a client-side interval. See /docs for the full
// honesty statement. This mirrors the same "simulate in the browser"
// approach used by the other satellite demos in this portfolio (e.g.
// Athena's requestAnimationFrame-driven drone paths).

import type {
  AssetKind,
  AssetSnapshot,
  AssetStatus,
  EventSeverity,
  EventType,
  SimEvent,
} from "./types";

