// --- Deterministic seeded PRNG (mulberry32) -----------------------------
// Used instead of Math.random() so a given simulation "seed" always
// produces the same event sequence — easier to reason about while
// tuning the demo, and honest: nothing here is cryptographically random.
function mulberry32(seed: number) {
  let a = seed;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function metersPerDegreeLat() {
  return 111_320;
}
function metersPerDegreeLng(lat: number) {
  return 111_320 * Math.cos((lat * Math.PI) / 180);
}

function orbitPosition(p: PatrolDef, elapsedSec: number) {
  const t = (elapsedSec / p.periodSec + p.phase) % 1;
  const angle = t * Math.PI * 2;
  const dLat = (p.radiusKm * 1000 * Math.sin(angle)) / metersPerDegreeLat();
  const dLng =
    (p.radiusKm * 1000 * Math.cos(angle)) / metersPerDegreeLng(p.centerLat);
  const lat = p.centerLat + dLat;
  const lng = p.centerLng + dLng;
  // Heading = direction of travel along the circle (tangent), degrees from north.
  const headingRad = angle + Math.PI / 2;
  const heading = ((headingRad * 180) / Math.PI + 360) % 360;
  return { lat, lng, heading };
}

export interface AssetRuntime {
  def: PatrolDef | SensorDef;
  kind: AssetKind;
  batteryPct: number;
  linkQuality: number;
  status: AssetStatus;
  rtb: boolean;
  faulted: boolean;
  startedAtSec: number;
}

export class ArgusSimulator {
  private rng: () => number;
  private elapsedSec = 0;
  private runtimes: Map<string, AssetRuntime> = new Map();
  private events: SimEvent[] = [];
  private eventSeq = 0;
  private simStartMs: number;

  constructor(seed = 20260101) {
    this.rng = mulberry32(seed);
    this.simStartMs = Date.now();
    for (const p of PATROLS) {
      this.runtimes.set(p.id, {
        def: p,
        kind: "uav",
        batteryPct: 78 + this.rng() * 18,
        linkQuality: 88 + this.rng() * 10,
        status: "nominal",
        rtb: false,
        faulted: false,
        startedAtSec: this.rng() * 60,
      });
    }
    for (const s of SENSORS) {
      this.runtimes.set(s.id, {
        def: s,
        kind: "sensor",
        batteryPct: 60 + this.rng() * 35,
        linkQuality: 90 + this.rng() * 8,
        status: "nominal",
        rtb: false,
        faulted: false,
        startedAtSec: 0,
      });
    }
  }

  private pushEvent(
    type: EventType,
    severity: EventSeverity,
    assetId: string,
    assetCallsign: string,
    message: string
  ) {
    this.eventSeq += 1;
    this.events.unshift({
      id: `evt-${this.eventSeq}`,
      ts: this.simStartMs + this.elapsedSec * 1000,
      type,
      severity,
      assetId,
      assetCallsign,
      message,
      acknowledged: false,
    });
    if (this.events.length > 60) this.events.length = 60;
  }

  /** Advance the simulation by `dtSec` seconds of simulated time. */
  tick(dtSec: number) {
    this.elapsedSec += dtSec;

    for (const [id, rt] of this.runtimes) {
      const callsign = rt.def.callsign;

      // Battery drain: UAVs drain while flying, recover while RTB; sensors
      // drain slowly and "recharge" (solar) in small increments.
      if (rt.kind === "uav") {
        if (rt.rtb) {
          rt.batteryPct = Math.min(100, rt.batteryPct + dtSec * 0.35);
          if (rt.batteryPct > 92) {
            rt.rtb = false;
            this.pushEvent("task_complete", "info", id, callsign, `${callsign} returned to base and resumed patrol.`);
          }
        } else {
          rt.batteryPct = Math.max(0, rt.batteryPct - dtSec * 0.045);
          if (rt.batteryPct < 22 && !rt.rtb) {
            rt.rtb = true;
            this.pushEvent("low_battery", "warning", id, callsign, `${callsign} battery at ${rt.batteryPct.toFixed(0)}% — recalling to base.`);
          }
        }
      } else {
        rt.batteryPct = Math.max(0, Math.min(100, rt.batteryPct - dtSec * 0.01 + (this.rng() - 0.45) * dtSec * 0.02));
      }

      // Link quality: small random walk, with occasional degradation events.
      rt.linkQuality = clamp(rt.linkQuality + (this.rng() - 0.5) * dtSec * 1.6, 5, 100);
      if (rt.linkQuality < 35 && this.rng() < dtSec * 0.02) {
        this.pushEvent("link_degraded", "warning", id, callsign, `${callsign} link quality degraded to ${rt.linkQuality.toFixed(0)}%.`);
      }
      if (rt.linkQuality < 12 && this.rng() < dtSec * 0.01) {
        this.pushEvent("link_lost", "critical", id, callsign, `${callsign} signal lost — last known position holding.`);
      }

      // Random fault injection (sensors) / calibration drift (UAVs).
      if (!rt.faulted && this.rng() < dtSec * 0.0025) {
        rt.faulted = true;
        if (rt.kind === "sensor") {
          this.pushEvent("sensor_fault", "warning", id, callsign, `${callsign} reporting anomalous readings — flagged for diagnostics.`);
        } else {
          this.pushEvent("calibration_drift", "caution", id, callsign, `${callsign} gimbal calibration drift detected.`);
        }
      }
      if (rt.faulted && this.rng() < dtSec * 0.01) {
        rt.faulted = false;
      }

      // Rare geofence breach (UAVs only, cosmetic — no real geofence data).
      if (rt.kind === "uav" && this.rng() < dtSec * 0.0015) {
        this.pushEvent("geofence_breach", "critical", id, callsign, `${callsign} drifted outside ${(rt.def as PatrolDef).sector} boundary — verify position.`);
      }

      // Weather hazard, portfolio-wide, low frequency.
      if (this.rng() < dtSec * 0.0006) {
        this.pushEvent("weather_hazard", "caution", id, callsign, `Gusting wind reported near ${(rt.def as PatrolDef).sector ?? "sensor post"} — monitor stability.`);
      }

      rt.status = deriveStatus(rt);
    }
  }

  snapshot(): { assets: AssetSnapshot[]; events: SimEvent[]; clock: number } {
    const assets: AssetSnapshot[] = [];
    for (const [id, rt] of this.runtimes) {
      if (rt.kind === "uav") {
        const p = rt.def as PatrolDef;
        const { lat, lng, heading } = orbitPosition(p, this.elapsedSec + rt.startedAtSec);
        assets.push({
          id,
          callsign: p.callsign,
          kind: "uav",
          task: rt.rtb ? "Returning to base" : p.task,
          sector: p.sector,
          lat,
          lng,
          heading,
          altitudeM: rt.rtb ? Math.max(40, p.altitudeM * (rt.batteryPct / 100)) : p.altitudeM,
          speedKmh: rt.rtb ? p.cruiseSpeedKmh * 1.15 : p.cruiseSpeedKmh,
          batteryPct: rt.batteryPct,
          linkQuality: rt.linkQuality,
          status: rt.status,
          faulted: rt.faulted,
          lastUpdated: this.simStartMs + this.elapsedSec * 1000,
        });
      } else {
        const s = rt.def as SensorDef;
        assets.push({
          id,
          callsign: s.callsign,
          kind: "sensor",
          task: "Fixed monitoring post",
          sector: s.sector,
          lat: s.lat,
          lng: s.lng,
          heading: 0,
          altitudeM: 0,
          speedKmh: 0,
          batteryPct: rt.batteryPct,
          linkQuality: rt.linkQuality,
          status: rt.status,
          faulted: rt.faulted,
          lastUpdated: this.simStartMs + this.elapsedSec * 1000,
        });
      }
    }
    return { assets, events: this.events.slice(), clock: this.simStartMs + this.elapsedSec * 1000 };
  }
}

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v));
}

function deriveStatus(rt: AssetRuntime): AssetStatus {
  if (rt.linkQuality < 12) return "offline";
  if (rt.batteryPct < 15 || rt.linkQuality < 30 || rt.faulted) return "critical";
  if (rt.batteryPct < 25 || rt.linkQuality < 45) return "warning";
  if (rt.batteryPct < 40 || rt.linkQuality < 65) return "caution";
  return "nominal";
}
